BEGIN TRANSACTION READ ONLY;
SELECT p.prosecdef AS security_definer,p.proconfig AS settings,md5(regexp_replace(p.prosrc,'\s+','','g')) AS body_md5,has_function_privilege('anon',p.oid,'EXECUTE') AS anon_execute,has_function_privilege('authenticated',p.oid,'EXECUTE') AS authenticated_execute,has_function_privilege('service_role',p.oid,'EXECUTE') AS service_role_execute,(SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version='20261101000000') AS migration_rows,(SELECT count(*) FROM auth.users WHERE email LIKE '%@bedos-status-test.invalid') AS fixture_users,(SELECT count(*) FROM pg_trigger WHERE tgname='bedos_status_test_audit') AS test_triggers,(SELECT count(*) FROM public.services WHERE name='Status access fixture') AS test_services,(SELECT jsonb_object_agg(proname,md5(regexp_replace(prosrc,'\s+','','g'))) FROM pg_proc p2 JOIN pg_namespace n2 ON n2.oid=p2.pronamespace WHERE n2.nspname='public' AND p2.proname IN ('get_user_role','update_own_profile')) AS dependency_hashes FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='bedos_update_user_status';
COMMIT;
